{"file_path":"src/address.js","content":"/**
 * Cell address handling: parsing an uppercased word into a column/row pair,
 * translating columns between letters and numbers, and ordering addresses
 * for output (ascending column, then ascending row).
 */

const ADDRESS_RE = /^([A-Z]{1,2})([0-9]{1,3})$/

/**
 * Parses an already-uppercased word as a cell address. Returns
 * `{ valid: true, col, row, address }` when it names an addressable cell
 * (column A..ZZ, row 1..999), where `col` is the column's 1-based number
 * and `address` is the canonical `<letters><digits>` string. Otherwise
 * returns `{ valid: false }`.
 */
export function parseAddress(word) {
  const m = ADDRESS_RE.exec(word)
  if (!m) return { valid: false }
  const row = Number(m[2])
  if (row < 1) return { valid: false }
  return { valid: true, col: colToNumber(m[1]), row, address: word }
}

/** Converts column letters (`A`..`ZZ`) to their 1-based column number. */
export function colToNumber(letters) {
  let n = 0
  for (const ch of letters) n = n * 26 + (ch.charCodeAt(0) - 64)
  return n
}

/** Converts a 1-based column number back to its letters (`A`..`ZZ`). */
export function numberToCol(n) {
  let s = ''
  while (n > 0) {
    const rem = (n - 1) % 26
    s = String.fromCharCode(65 + rem) + s
    n = Math.floor((n - 1) / 26)
  }
  return s
}

/** Builds the canonical address string for a column number and row. */
export function makeAddress(col, row) {
  return `${numberToCol(col)}${row}`
}

/** Orders two addressable cells by ascending column, then ascending row. */
export function compareAddresses(a, b) {
  const pa = parseAddress(a)
  const pb = parseAddress(b)
  if (pa.col !== pb.col) return pa.col - pb.col
  return pa.row - pb.row
}
"}

