{"file_path":"src/formula.js","content":"/**
 * Tokenizer and recursive-descent parser for formula bodies (the text after
 * the leading `=`). Produces an AST or `null` when the grammar rejects the
 * text. See the module-level comments below for the grammar shape.
 */

import { parseAddress } from './address.js'

const TWO_CHAR_OPS = ['<=', '>=', '<>']
const ONE_CHAR_OPS = ['^', '*', '/', '+', '-', '=', '<', '>', '(', ')', ',', ':']
const COMPARISON_OPS = new Set(['=', '<>', '<', '<=', '>', '>='])

class ParseFailure extends Error {}

function tokenize(text) {
  const tokens = []
  let i = 0
  while (i < text.length) {
    const ch = text[i]
    if (ch === ' ' || ch === '\t') {
      i += 1
      continue
    }
    if (/[0-9]/.test(ch)) {
      const m = /^[0-9]+(\.[0-9]+)?/.exec(text.slice(i))
      tokens.push({ type: 'NUMBER', value: m[0] })
      i += m[0].length
      continue
    }
    if (/[A-Za-z]/.test(ch)) {
      const m = /^[A-Za-z][A-Za-z0-9]*/.exec(text.slice(i))
      tokens.push({ type: 'WORD', value: m[0] })
      i += m[0].length
      continue
    }
    const two = text.slice(i, i + 2)
    if (TWO_CHAR_OPS.includes(two)) {
      tokens.push({ type: 'OP', value: two })
      i += 2
      continue
    }
    if (ONE_CHAR_OPS.includes(ch)) {
      tokens.push({ type: 'OP', value: ch })
      i += 1
      continue
    }
    throw new ParseFailure(`unexpected character ${ch}`)
  }
  return tokens
}

class Parser {
  constructor(tokens) {
    this.tokens = tokens
    this.pos = 0
  }

  peek(offset = 0) {
    return this.tokens[this.pos + offset]
  }

  next() {
    return this.tokens[this.pos++]
  }

  expectOp(value) {
    const t = this.peek()
    if (!t || t.type !== 'OP' || t.value !== value) throw new ParseFailure(`expected ${value}`)
    this.pos += 1
  }

  parseComparison() {
    let left = this.parseAdditive()
    while (this.peek() && this.peek().type === 'OP' && COMPARISON_OPS.has(this.peek().value)) {
      const op = this.next().value
      const right = this.parseAdditive()
      left = { type: 'Bin', op, left, right }
    }
    return left
  }

  parseAdditive() {
    let left = this.parseMultiplicative()
    while (this.peek() && this.peek().type === 'OP' && (this.peek().value === '+' || this.peek().value === '-')) {
      const op = this.next().value
      const right = this.parseMultiplicative()
      left = { type: 'Bin', op, left, right }
    }
    return left
  }

  parseMultiplicative() {
    let left = this.parsePower()
    while (this.peek() && this.peek().type === 'OP' && (this.peek().value === '*' || this.peek().value === '/')) {
      const op = this.next().value
      const right = this.parsePower()
      left = { type: 'Bin', op, left, right }
    }
    return left
  }

  parsePower() {
    const left = this.parseUnary()
    if (this.peek() && this.peek().type === 'OP' && this.peek().value === '^') {
      this.next()
      const right = this.parsePower()
      return { type: 'Bin', op: '^', left, right }
    }
    return left
  }

  parseUnary() {
    const t = this.peek()
    if (t && t.type === 'OP' && (t.value === '-' || t.value === '+')) {
      this.next()
      const expr = this.parseAtom()
      return { type: 'Unary', op: t.value, expr }
    }
    return this.parseAtom()
  }

  parseAtom() {
    const t = this.peek()
    if (!t) throw new ParseFailure('unexpected end of formula')
    if (t.type === 'NUMBER') {
      this.next()
      return { type: 'Num', value: Number(t.value) }
    }
    if (t.type === 'OP' && t.value === '(') {
      this.next()
      const inner = this.parseComparison()
      this.expectOp(')')
      return inner
    }
    if (t.type === 'WORD') {
      this.next()
      const upper = t.value.toUpperCase()
      if (upper === 'TRUE') return { type: 'Bool', value: true }
      if (upper === 'FALSE') return { type: 'Bool', value: false }
      if (this.peek() && this.peek().type === 'OP' && this.peek().value === '(') {
        this.next()
        const args = this.parseArgs()
        return { type: 'Call', name: upper, args }
      }
      const info = parseAddress(upper)
      return { type: 'Cell', valid: info.valid, address: info.valid ? info.address : null }
    }
    throw new ParseFailure('unexpected token')
  }

  parseArgs() {
    const args = []
    if (this.peek() && this.peek().type === 'OP' && this.peek().value === ')') {
      this.next()
      return args
    }
    for (;;) {
      args.push(this.parseArgument())
      const t = this.peek()
      if (t && t.type === 'OP' && t.value === ',') {
        this.next()
        continue
      }
      if (t && t.type === 'OP' && t.value === ')') {
        this.next()
        break
      }
      throw new ParseFailure('expected , or )')
    }
    return args
  }

  // A range is only grammatical directly as a whole function argument, so
  // this checks for that exact `WORD : WORD` shape before falling back to a
  // normal expression (which will fail to parse if a stray `:` remains).
  parseArgument() {
    const a = this.peek(0)
    const colon = this.peek(1)
    const b = this.peek(2)
    const after = this.peek(3)
    if (
      a && a.type === 'WORD' &&
      colon && colon.type === 'OP' && colon.value === ':' &&
      b && b.type === 'WORD' &&
      after && after.type === 'OP' && (after.value === ',' || after.value === ')')
    ) {
      this.pos += 3
      const info1 = parseAddress(a.value.toUpperCase())
      const info2 = parseAddress(b.value.toUpperCase())
      const valid = info1.valid && info2.valid
      return {
        type: 'Range',
        valid,
        col1: valid ? info1.col : null,
        row1: valid ? info1.row : null,
        col2: valid ? info2.col : null,
        row2: valid ? info2.row : null,
      }
    }
    return this.parseComparison()
  }
}

/** Parses a formula body (without the leading `=`). Returns the AST, or
 * `null` when the grammar does not accept the text. */
export function parseFormula(text) {
  try {
    const tokens = tokenize(text)
    const parser = new Parser(tokens)
    const ast = parser.parseComparison()
    if (parser.pos !== tokens.length) return null
    return ast
  } catch (e) {
    if (e instanceof ParseFailure) return null
    throw e
  }
}
"}

