/** Parses a formula body (without the leading `=`). Returns the AST, or
 * `null` when the grammar does not accept the text. */
export function parseFormula(text) {
  try {
    const tokens = tokenize(text)
    const parser = new Parser(tokens)
    const ast = parser.parseComparison()
    if (parser.pos !== tokens.length) return null
    return ast
  } catch (e) {
    if (e instanceof ParseFailure) return null
    throw e
  }
}
"}

