        return { type: 'Call', name: upper, args }
      }
      const info = parseAddress(upper)
      return { type: 'Cell', valid: info.valid, address: info.valid ? info.address : null }
    }
    throw new ParseFailure('unexpected token')
  }

  parseArgs() {
    const args = []
    if (this.peek() && this.peek().type === 'OP' && this.peek().value === ')') {
      this.next()
      return args
    }
    for (;;) {
      args.push(this.parseArgument())
      const t = this.peek()
      if (t && t.type === 'OP' && t.value === ',') {
        this.next()
        continue
      }
      if (t && t.type === 'OP' && t.value === ')') {
