{"file_path":"src/values.js","content":"/**
 * Cell value representation (`number`, `text`, `bool`, or `error`) and how
 * each prints in `values` mode.
 */

export const NUMBER = (value) => ({ type: 'number', value })
export const TEXT = (value) => ({ type: 'text', value })
export const BOOL = (value) => ({ type: 'bool', value })
export const ERROR = (value) => ({ type: 'error', value })

export const ERROR_TOKENS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']

/** Rounds a finite, nonzero number to ten significant digits. */
function roundToTenSigFigs(n) {
  if (n === 0) return 0
  const rounded = Number(n.toPrecision(10))
  return rounded === 0 ? 0 : rounded
}

/** Formats a value the way `values` mode prints it. */
export function formatValue(value) {
  switch (value.type) {
    case 'number': {
      const n = roundToTenSigFigs(value.value)
      return Object.is(n, -0) ? '0' : String(n)
    }
    case 'error':
      return value.value
    case 'bool':
      return value.value ? 'TRUE' : 'FALSE'
    case 'text':
      return value.value
    default:
      throw new Error(`unreachable value type ${value.type}`)
  }
}

/** Reads a value as a number for arithmetic: booleans become 1/0, text
 * becomes `#VALUE!`, and errors pass through unchanged. */
export function toNumber(value) {
  if (value.type === 'number') return value
  if (value.type === 'bool') return NUMBER(value.value ? 1 : 0)
  if (value.type === 'error') return value
  return ERROR('#VALUE!')
}
"}

