{"file_path":"src/sheet.js","content":"/**
 * Parses the sheet text read from standard input into a map of address to
 * raw cell content, applying the line-splitting and address rules from the
 * spec. Throws a `SheetError` (line number + message) on the first invalid
 * address or duplicate declaration.
 */

import { parseAddress } from './address.js'

export class SheetError extends Error {
  constructor(message) {
    super(message)
  }
}

/** Parses sheet text into a `Map` from canonical address to raw content. */
export function parseSheet(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const cells = new Map()
  lines.forEach((line, i) => {
    const lineNo = i + 1
    const stripped = line.replace(/^[ \t]+/, '')
    if (stripped === '' || stripped.startsWith('#')) return

    const m = /[ \t]/.exec(stripped)
    const rawAddress = m ? stripped.slice(0, m.index) : stripped
    const rest = m ? stripped.slice(m.index) : ''
    const content = rest.replace(/^[ \t]+/, '')

    const upper = rawAddress.toUpperCase()
    const info = parseAddress(upper)
    if (!info.valid) throw new SheetError(`line ${lineNo}: invalid cell address ${upper}`)
    if (cells.has(upper)) throw new SheetError(`line ${lineNo}: cell ${upper} is declared twice`)
    cells.set(upper, content)
  })

  return cells
}
"}

