{"file_path":"src/evaluate.js","content":"/**
 * Evaluates a parsed sheet's cells into values, following formulas,
 * expanding ranges, and detecting reference cycles.
 */

import { parseFormula } from './formula.js'
import { NUMBER, TEXT, BOOL, ERROR, ERROR_TOKENS, toNumber } from './values.js'
import { makeAddress } from './address.js'

const LITERAL_NUMBER_RE = /^-?[0-9]+(\.[0-9]+)?$/

const FUNCTION_ARITY = {
  SUM: { min: 1, max: Infinity },
  MIN: { min: 1, max: Infinity },
  MAX: { min: 1, max: Infinity },
  COUNT: { min: 1, max: Infinity },
  AVG: { min: 1, max: Infinity },
  ABS: { min: 1, max: 1 },
  IF: { min: 3, max: 3 },
}

/** Classifies raw cell content as a literal value or a parsed formula
 * (whose AST is `null` when the grammar rejects the text). */
export function classifyContent(content) {
  if (content.startsWith('=')) {
    return { kind: 'formula', ast: parseFormula(content.slice(1)) }
  }
  if (content === '') return { kind: 'literal', value: NUMBER(0) }
  if (ERROR_TOKENS.includes(content)) return { kind: 'literal', value: ERROR(content) }
  if (LITERAL_NUMBER_RE.test(content)) return { kind: 'literal', value: NUMBER(Number(content)) }
  return { kind: 'literal', value: TEXT(content) }
}

class CycleSignal {
  constructor(origin) {
    this.origin = origin
  }
}

function numericResult(n) {
  return Number.isFinite(n) ? NUMBER(n) : ERROR('#DIV/0!')
}

/** Builds an evaluator over a sheet's declared cells (address -> raw
 * content). `evaluate(address)` returns that cell's value, or `NUMBER(0)`
 * for an undeclared cell; cycles resolve to `#CYCLE!` for every cell in
 * the loop. */
export function createEvaluator(cells) {
  const memo = new Map()
  const inProgress = new Set()

  function evaluate(address) {
    if (memo.has(address)) return memo.get(address)
    if (!cells.has(address)) return NUMBER(0)
    if (inProgress.has(address)) throw new CycleSignal(address)

    inProgress.add(address)
    try {
      const { kind, ast, value } = classifyContent(cells.get(address))
      let result
      if (kind === 'literal') {
        result = value
      } else if (ast === null) {
