      return result
    } catch (e) {
      if (e instanceof CycleSignal) {
        const result = ERROR('#CYCLE!')
        memo.set(address, result)
        if (e.origin === address) return result
        throw e
      }
      throw e
    } finally {
      inProgress.delete(address)
    }
  }

  function evalExpr(node) {
    switch (node.type) {
      case 'Num':
        return NUMBER(node.value)
      case 'Bool':
        return BOOL(node.value)
      case 'Cell':
        return node.valid ? evaluate(node.address) : ERROR('#REF!')
      case 'Unary': {
        const v = evalExpr(node.expr)
        if (v.type === 'error') return v
        const n = toNumber(v)
        if (n.type === 'error') return n
        return numericResult(node.op === '-' ? -n.value : n.value)
      }
      case 'Bin': {
        const l = evalExpr(node.left)
        if (l.type === 'error') return l
        const r = evalExpr(node.right)
        if (r.type === 'error') return r
        return applyBinOp(node.op, l, r)
      }
      case 'Call':
        return evalCall(node.name, node.args)
      default:
        throw new Error(`unreachable node type ${node.type}`)
    }
  }

  // Expands one function argument to its list of contributed values: a
  // plain expression contributes one value, a range contributes every cell
  // it covers in ascending column then row order.
  function expandArg(node) {
    if (node.type === 'Range') {
      if (!node.valid) return [ERROR('#REF!')]
      const cmin = Math.min(node.col1, node.col2)
      const cmax = Math.max(node.col1, node.col2)
      const rmin = Math.min(node.row1, node.row2)
      const rmax = Math.max(node.row1, node.row2)
      const list = []
      for (let c = cmin; c <= cmax; c++) {
        for (let r = rmin; r <= rmax; r++) list.push(evaluate(makeAddress(c, r)))
      }
      return list
    }
    return [evalExpr(node)]
  }

  // Reads an argument (scalar expression, or a range that must resolve to
  // exactly one cell) as a single value.
  function evalScalarArg(node) {
    const list = expandArg(node)
    for (const v of list) if (v.type === 'error') return v
    if (list.length !== 1) return ERROR('#VALUE!')
    return list[0]
  }

  function evalCall(name, args) {
    const arity = FUNCTION_ARITY[name]
    if (!arity) return ERROR('#NAME?')
    if (args.length < arity.min || args.length > arity.max) return ERROR('#ERR!')
    if (name === 'IF') return evalIf(args)
    if (name === 'ABS') return evalAbs(args[0])
    return evalAggregate(name, args)
  }

  function evalAbs(node) {
    const v = evalScalarArg(node)
    if (v.type === 'error') return v
    const n = toNumber(v)
    if (n.type === 'error') return n
    return numericResult(Math.abs(n.value))
  }

  function evalIf(args) {
    const condVal = evalScalarArg(args[0])
    if (condVal.type === 'error') return condVal
    let cond
    if (condVal.type === 'bool') cond = condVal.value
    else if (condVal.type === 'number') cond = condVal.value !== 0
    else return ERROR('#VALUE!')
    return evalScalarArg(cond ? args[1] : args[2])
  }

  function evalAggregate(name, args) {
    const combined = []
    for (const a of args) combined.push(...expandArg(a))
    for (const v of combined) if (v.type === 'error') return v

    if (name === 'COUNT') {
      return NUMBER(combined.filter((v) => v.type === 'number').length)
    }

    const nums = []
    for (const v of combined) {
      const n = toNumber(v)
      if (n.type === 'error') return n
      nums.push(n.value)
    }
    if (name === 'SUM') return numericResult(nums.reduce((a, b) => a + b, 0))
    if (name === 'MIN') return numericResult(Math.min(...nums))
    if (name === 'MAX') return numericResult(Math.max(...nums))
    return numericResult(nums.reduce((a, b) => a + b, 0) / nums.length) // AVG
  }

  return { evaluate }
}

const TYPE_RANK = { number: 0, text: 1, bool: 2 }

function compareValues(l, r) {
  if (l.type === r.type) {
    if (l.type === 'number') return l.value - r.value
    if (l.type === 'text') return l.value < r.value ? -1 : l.value > r.value ? 1 : 0
    return (l.value ? 1 : 0) - (r.value ? 1 : 0)
  }
  return TYPE_RANK[l.type] - TYPE_RANK[r.type]
}

function applyBinOp(op, l, r) {
  if (op === '=' || op === '<>' || op === '<' || op === '<=' || op === '>' || op === '>=') {
    const cmp = compareValues(l, r)
    switch (op) {
      case '=':
        return BOOL(cmp === 0)
      case '<>':
        return BOOL(cmp !== 0)
      case '<':
        return BOOL(cmp < 0)
      case '<=':
        return BOOL(cmp <= 0)
      case '>':
        return BOOL(cmp > 0)
      default:
        return BOOL(cmp >= 0)
    }
  }

  const ln = toNumber(l)
  if (ln.type === 'error') return ln
  const rn = toNumber(r)
  if (rn.type === 'error') return rn
  if (op === '/' && rn.value === 0) return ERROR('#DIV/0!')

  switch (op) {
    case '+':
      return numericResult(ln.value + rn.value)
    case '-':
      return numericResult(ln.value - rn.value)
    case '*':
      return numericResult(ln.value * rn.value)
    case '/':
      return numericResult(ln.value / rn.value)
    case '^':
      return numericResult(Math.pow(ln.value, rn.value))
    default:
      throw new Error(`unreachable operator ${op}`)
  }
}
"}

