      if (node.valid) names.add(node.address)
      return
    case 'Unary':
      walk(node.expr, names)
      return
    case 'Bin':
      walk(node.left, names)
      walk(node.right, names)
      return
    case 'Call':
      for (const arg of node.args) walkArg(arg, names)
      return
    default:
      throw new Error(`unreachable node type ${node.type}`)
  }
}

