{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js values` prints the value of every cell in the
 * sheet read from standard input, and `node src/cli.js deps` prints the cells
 * each one reads.
 */

import { readFileSync } from 'node:fs'
import { parseSheet, SheetError } from './sheet.js'
import { createEvaluator } from './evaluate.js'
import { collectDeps } from './deps.js'
import { compareAddresses } from './address.js'
import { formatValue } from './values.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'values' && args[0] !== 'deps')) {
    fail('usage: cli.js values|deps')
  }
  const mode = args[0]

  const input = readFileSync(0, 'utf8')
  let cells
  try {
    cells = parseSheet(input)
  } catch (e) {
    if (e instanceof SheetError) fail(e.message)
    throw e
  }

  const addresses = [...cells.keys()].sort(compareAddresses)
  const lines = []

  if (mode === 'values') {
    const { evaluate } = createEvaluator(cells)
    for (const address of addresses) lines.push(`${address}=${formatValue(evaluate(address))}`)
  } else {
    for (const address of addresses) {
      const deps = [...collectDeps(cells.get(address))].sort(compareAddresses)
      lines.push(`${address}:${deps.map((d) => ` ${d}`).join('')}`)
    }
  }

  process.stdout.write(lines.map((l) => `${l}\n`).join(''))
}

main()
"}

